import json, random, sys, time
sys.path.insert(0,'/workspace/tmp'); sys.path.insert(0,'/workspace/submission')
import main as impl

def mk(services, atom_specs, action='allow', op='contains'):
    rules = []
    for i, p in enumerate(atom_specs):
        rules.append({'action': action if i % 2 == 0 else 'allow',
                      'when': {'op': op, 'path': list(p)}})
    return {'services': services, 'rules': rules, 'queries': [[], [services[0]]]}

def compile_size(services, specs, op='contains'):
    req = mk(services, specs, op=op)
    parsed = impl.parse_request(json.loads(json.dumps(req)))
    try:
        order, trans, const_truth, kept, truth, nrep, col_of = impl.build_product(parsed['atoms'], len(services))
    except impl.ComplexityError:
        return '>20000', None
    n = len(order)
    t0 = time.time()
    out = json.loads(impl.compile_bundle(parsed))
    return n, (len(out['dfa']['next']), round(time.time()-t0, 3))

rng = random.Random(11)
for op in ('contains','endswith','match','startswith'):
    for L in (6,8,10,12,14,16):
        for k in (4,6,8,10):
            specs = [tuple(rng.choice(['a','b']) for _ in range(L)) for _ in range(k)]
            n, info = compile_size(['a','b'], specs, op)
            print('%-10s L=%2d k=%2d product=%-8s min=%s' % (op, L, k, n, info))
EOF
